@startuml
class Airline {
  +id : string
}

class Flight {
  +id : string
  +departureTime : datetime
  +arrivalTime : datetime
}

class Airport {
  +id : string
}

class Aircraft {
  +type : string
  +isWorking : boolean
  +isAirborne : boolean
}

class Pilot {
  +experienceLevel : int
}

class AeroplaneType {
  +name : string
}

class RoleRequirement {
  +role : string
  +requiredCount : int
}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departure airport
Flight "*" -- "1" Airport : arrival airport
Flight "1" -- "1" Pilot : captain
Flight "1" -- "1" Pilot : co-pilot
Flight "*" -- "1" Aircraft : uses
AeroplaneType "1" -- "*" Aircraft : is type of
AeroplaneType "1" -- "*" RoleRequirement : requires

Pilot "1..*" -- "1" Airline : works for
Pilot "1" -- "1" AeroplaneType : has level requirement for
@enduml

